import numpy as np
import pandas as pd

# Test cases with dtype="c8" and dtype_equal variations
# These appear to be testing dtype comparison with complex64 (c8)

try:
    # Case 1: dtype_equal=True with c8
    result1 = pd.DataFrame(np.array([1+2j, 3+4j], dtype='c8')).equals(
        pd.DataFrame(np.array([1+2j, 3+4j], dtype='c8'))
    )
    probe("same four cases with dtype=\"c8\" (and dtype_equal=True); dtype_equal=False already returns the expected values - case 1", result1)
except Exception as e:
    probe_exception("same four cases with dtype=\"c8\" (and dtype_equal=True); dtype_equal=False already returns the expected values - case 1", e)

try:
    # Case 2: dtype_equal=True with c8, different values
    result2 = pd.DataFrame(np.array([1+2j, 3+4j], dtype='c8')).equals(
        pd.DataFrame(np.array([5+6j, 7+8j], dtype='c8'))
    )
    probe("same four cases with dtype=\"c8\" (and dtype_equal=True); dtype_equal=False already returns the expected values - case 2", result2)
except Exception as e:
    probe_exception("same four cases with dtype=\"c8\" (and dtype_equal=True); dtype_equal=False already returns the expected values - case 2", e)

try:
    # Case 3: dtype_equal=True with c8, NaN values
    result3 = pd.DataFrame(np.array([np.nan+2j, 3+np.nan*1j], dtype='c8')).equals(
        pd.DataFrame(np.array([np.nan+2j, 3+np.nan*1j], dtype='c8'))
    )
    probe("same four cases with dtype=\"c8\" (and dtype_equal=True); dtype_equal=False already returns the expected values - case 3", result3)
except Exception as e:
    probe_exception("same four cases with dtype=\"c8\" (and dtype_equal=True); dtype_equal=False already returns the expected values - case 3", e)

try:
    # Case 4: dtype_equal=True with c8, mixed types
    result4 = pd.DataFrame(np.array([1+0j, 2+0j], dtype='c8')).equals(
        pd.DataFrame(np.array([1.0, 2.0], dtype='f4'))
    )
    probe("same four cases with dtype=\"c8\" (and dtype_equal=True); dtype_equal=False already returns the expected values - case 4", result4)
except Exception as e:
    probe_exception("same four cases with dtype=\"c8\" (and dtype_equal=True); dtype_equal=False already returns the expected values - case 4", e)

